import json,time,hashlib,csv
from pathlib import Path
R=Path('bench/g1');old=json.loads((R/'selection_freeze_v2.json').read_text());rows=old['comparisons'];eligible=[x for x in rows if x['absent_specificity']>=.85];best=max(eligible,key=lambda x:(x['accuracy'],-x['mean_model_ms']))
freeze=dict(source='[시뮬인식]',gt_assist=False,split='tuning',revision='2r-final',frozen_at=time.time(),prior_v1_sha256=old['prior_freeze_sha256'],superseded_v2_sha256=old['sha256'],rule='among a,b,c x .35/.45/.55 with absent specificity>=.85 maximize correct selection accuracy, tie minimize instruction latency; final no further changes',safety_floor=.85,safety_floor_basis='parent chose .85 from tuning b.35 specificity .878; not eval-derived',selected=best,comparisons=rows,width=640,height=480,area_cap=.04,text_threshold=.25,model_revision=old['model_revision'],chronology='v1 precollection; v2 strict-error rule superseded due refusal degeneration; v2r final frozen before any outcome interpretation; raw collection ongoing/sealed')
freeze['sha256']=hashlib.sha256(json.dumps(freeze,sort_keys=True).encode()).hexdigest();(R/'selection_freeze_v2r.json').write_text(json.dumps(freeze,indent=2))
with (R/'selection_tune_candidates_v2r.csv').open('w') as f:
 fields=['mode','threshold','n','correct','accuracy','absent_n','absent_correct','absent_specificity','wrong_present','wrong_total','no_detection','mean_model_ms'];w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(rows)
lines=['\n## v2r final frozen policy, tuning-only comparison','Rule: absent specificity >=85%, then max correct-selection accuracy, tie min instruction latency. 85% chosen from tune b.35=87.8%; no further changes.','| mode | threshold | correct/n | absent correct/n | wrong present | ms/instruction |','|---|---:|---:|---:|---:|---:|']
for x in rows:lines.append(f"| {x['mode']} | {x['threshold']} | {x['correct']}/{x['n']} ({x['accuracy']:.4f}) | {x['absent_correct']}/{x['absent_n']} ({x['absent_specificity']:.4f}) | {x['wrong_present']} | {x['mean_model_ms']:.2f} |")
lines.append('Selected='+best['mode']+',threshold='+str(best['threshold'])+', hash='+freeze['sha256'])
with Path('notes/g1_results.md').open('a') as f:f.write('\n'.join(lines)+'\n')
